import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts mixed case text with punctuation to lowercase hyphen-separated slug", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });

  test("normalizes whitespace and underscores to single hyphens", () => {
    expect(slugify("  Foo__Bar  ")).toBe("foo-bar");
  });

  test("collapses multiple consecutive hyphens to single hyphen", () => {
    expect(slugify("a---b")).toBe("a-b");
  });

  test("returns empty string for empty input", () => {
    expect(slugify("")).toBe("");
  });

  test("returns empty string for special-characters-only input", () => {
    expect(slugify("!@#$%")).toBe("");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("-abc-")).toBe("abc");
  });

  test("handles complex input with mixed special characters, spaces, and underscores", () => {
    expect(slugify("The Quick_Brown  Fox!!!")).toBe("the-quick-brown-fox");
  });

  test("preserves alphanumeric characters", () => {
    expect(slugify("Test123")).toBe("test123");
  });

  test("handles input with only hyphens", () => {
    expect(slugify("---")).toBe("");
  });
});

